"""Generate opening trees, supporting additions and narrative/policy content.

Run the Continental War generator first; this command does not rewrite its files.
--check compares generated bytes without changing the candidate.
"""
import argparse,json,re,sys
from pathlib import Path
from content import FOCUSES,partner
from narrative import BRANCHES
from fcu_content import OPTIONS as FCU_OPTIONS, POLICIES as FCU_POLICIES
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[1];MOD=ROOT/'mod/2985041246'
sys.path.insert(0,str(ROOT/'tools'))
from usea_expansion.script import parse,get,render

OUT={};LOC={};EFFECTS=[];EVENTS=['add_namespace = ac_expansion'];IDEAS=[]
TAGS=('ERU','FCU','NPT','REC','YUK')
def block(k,b):return k+' = {\n'+ '\n'.join('\t'+l.rstrip() if l.strip() else '' for l in b.splitlines())+'\n}\n'
def loc(k,v):
    assert k not in LOC,k
    LOC[k]=v
def once(flag,body,condition='ac_exp_eligible = yes'):
    return block('if','limit = { '+condition+' NOT = { has_country_flag = '+flag+' } }\nset_country_flag = '+flag+'\n'+body)
def put(path,text):OUT[path]=text

def focus(row):
    ident=row.id;loc(ident,row.title);loc(ident+'_desc',row.desc)
    available=('original_tag = '+row.tag+' ac_exp_eligible = yes '+row.available).strip()
    if row.phase=='opening':available+=' NOT = { has_global_flag = ac_ucw_calendar_started } date < 1999.12.1'
    reward=row.reward
    if row.suffix in ('opening','island_accounts','district_inventory','industrial_inventory'):
        reward+='\ncustom_effect_tooltip = ac_exp_opening_brief_tt'
    if row.suffix=='opening_assessment':reward='set_country_flag = '+row.tag+'_exp_opening_reviewed\nadd_stability = 0.02'
    if row.id=='YUK_exp_data_protocols':
        reward+='\n'+block('if','limit = { '+partner('OSE')+' has_country_flag = ac_yuk_arkbird_partner }\nadd_opinion_modifier = { target = OSE modifier = ac_exp_scientific_exchange }\nOSE = { add_opinion_modifier = { target = YUK modifier = ac_exp_scientific_exchange } }')
    body=f'id = {ident}\nicon = GFX_ac_exp_{ident}\nx = {row.x}\ny = {row.y}\ncost = {row.cost}\nai_will_do = {{ factor = 40 }}\n'
    if row.prerequisite:body+='prerequisite = { '+' '.join('focus = '+p for p in row.prerequisite)+' }\n'
    if row.excludes:body+='mutually_exclusive = { '+' '.join('focus = '+p for p in row.excludes)+' }\n'
    body+=block('available',available)+'cancel_if_invalid = yes\ncontinue_if_invalid = no\n'
    body+=block('completion_reward',once(ident+'_done',reward,available))+'search_filters = { }'
    return block('focus' if row.phase=='opening' else 'shared_focus',body)

def build_trees():
    for tag in ('ERU','FCU'):
        rows=[r for r in FOCUSES if r.tag==tag and r.phase=='opening']
        ident='ac_exp_'+tag.lower()+'_opening'
        loc(ident,('Erusea' if tag=='ERU' else 'Central Usea')+': the Opening Decade')
        loc(ident+'_desc','Administration, preparedness and continental relations, 1991–1999.')
        body='id = '+ident+'\ncountry = { factor = 0 modifier = { add = 20 original_tag = '+tag+' NOT = { has_global_flag = ac_ucw_calendar_started } date < 1999.12.1 } }\ndefault = no\ncontinuous_focus_position = { x = 1100 y = 1000 }\n'
        put('common/national_focus/'+tag+'_opening.txt',block('focus_tree',body+'\n'.join(focus(r) for r in rows)))
    for tag in ('NPT','REC','YUK'):
        rows=[r for r in FOCUSES if r.tag==tag and r.phase=='support']
        treepath='common/national_focus/'+tag+'.txt'
        source=(MOD/treepath).read_text(encoding='utf-8-sig')
        source=re.sub(r'\s*# BEGIN EXPANSION IMPORTS.*?# END EXPANSION IMPORTS','',source,flags=re.S)
        source=source.split('# BEGIN EXPANSION FOCUSES')[0].rstrip()+'\n'
        # Locate the first tree's closing brace without reformatting old content.
        start=source.index('{',source.index('focus_tree'));depth=1;end=start+1
        while depth:
            if source[end]=='{':depth+=1
            elif source[end]=='}':depth-=1
            end+=1
        imports='\n\t# BEGIN EXPANSION IMPORTS\n'+''.join('\tshared_focus = '+r.id+'\n' for r in rows)+'\t# END EXPANSION IMPORTS\n'
        source=source[:end-1]+imports+source[end-1:]
        definitions='# BEGIN EXPANSION FOCUSES\n'+''.join(focus(r) for r in rows)
        if tag=='NPT':
            path='common/national_focus/NPT_pre_continental_war.txt'
            old=(MOD/path).read_text(encoding='utf-8-sig').split('# BEGIN EXPANSION FOCUSES')[0].rstrip()+'\n\n'
            put(path,old+definitions)
        else:source+='\n'+definitions
        put(treepath,source)

COUNTRY_TEXT={
 'ERU':('Erusea','The Papers from Farbanti','The ministries have delivered their inventories to Farbanti. Some describe a capable state; others describe the same people and equipment promised to several departments at once. The cabinet can spend political authority on making the accounts honest, or leave more room for the services to resolve shortages internally. Neither choice predicts the disaster to come, but both will shape how the state responds to it.'),
 'FCU':('Central Usea','Promises around the Council Table','The treaty secretariat has collected enough figures to see where the promises overlap. The same transport capacity appears in several emergency plans, while some districts have promised assistance without naming who would deliver it. The council must choose whether to confront these discrepancies publicly or ask the services to settle them through a smaller coordinating staff.'),
 'NPT':('North Point','The Cost of an Island Mandate','The cabinet has inherited a mandate and a narrow margin for error. Imported fuel, harbour repairs and airfield maintenance compete with the services that island communities expect every day. The accounts now show what can be sustained. Ministers must decide whether to spend their authority on a public reckoning or strengthen the staff that will manage an emergency.'),
 'REC':('Recta','The District Ledgers','The first district ledgers have arrived at the republican offices. Some are complete; others contain lists of missing records and buildings whose purpose has changed repeatedly. Before reconstruction can become more than a promise, the administration needs a defensible account of what it governs. The existing territorial settlement remains the limit of this programme.'),
 'YUK':('Yuktobania','Capacity behind the Production Figures','The industrial inventory distinguishes what the ministries have planned from what their workshops can actually deliver. Rail dispatchers describe shortages that production reports barely mention. Civil administrators and the command staff agree that something must change, but disagree over who should have the authority to demand it.')}

def event_deadline(index):
    # A settlement's prerequisite chain can finish after 2005. Only the
    # concluding assessment stays open; historical/preparation choices expire.
    return '' if index==4 else ' date < 2005.12.31'

def event(tag,index,title,desc,options):
    if tag=='FCU':options=FCU_OPTIONS[index]
    number=TAGS.index(tag)*10+index;key='ac_expansion.'+str(number)
    flag=tag+'_exp_event_'+str(index)
    loc(key+'.t',title);loc(key+'.d',desc+'\n\nThese choices are authored alternatives within the campaign.')
    body='id = '+key+'\ntitle = '+key+'.t\ndesc = '+key+'.d\npicture = GFX_ac_exp_event_'+tag.lower()+('_domestic' if index<3 else '_crisis')+'\nis_triggered_only = yes\ntrigger = { original_tag = '+tag+' ac_exp_eligible = yes NOT = { has_country_flag = '+flag+'_answered }'+event_deadline(index)+' }\n'
    for i,(label,reward) in enumerate(options):
        option=key+'.'+chr(97+i);loc(option,label)
        body+=block('option','name = '+option+'\nai_chance = { factor = '+str(60 if i==0 else 40)+' }\n'+once(flag+'_answered',reward))
    EVENTS.append(block('country_event',body))

def build_narrative():
    dispatch=[]
    for tag,(name,title,desc) in COUNTRY_TEXT.items():
        event(tag,1,title,desc,[('Publish the account and accept the political cost.','add_political_power = -20\nadd_stability = 0.03'),('Strengthen the coordinating staff.','army_experience = 8\nadd_political_power = -10')])
        event(tag,2,*BRANCHES[tag][0],
            [('Adopt public review.','remove_ideas = '+tag+'_exp_directive\nadd_ideas = '+tag+'_exp_civil'),('Retain directive authority.','remove_ideas = '+tag+'_exp_civil\nadd_ideas = '+tag+'_exp_directive')])
        event(tag,3,*BRANCHES[tag][1],
            [('Protect the civilian relief allocation.',
              'add_political_power = -15\n'+once(tag+'_exp_relief_allocation','set_country_flag = '+tag+'_exp_prepared_relief\nif = { limit = { ac_ucw_active = yes } add_to_variable = { ac_ucw_pressure = -5 } ac_ucw_bound = yes }')),
             ('Retain trained readiness cadres.','army_experience = 12\nair_experience = 5\nadd_political_power = -20')])
        event(tag,4,*BRANCHES[tag][2],
            [('Keep a standing recovery service.','add_ideas = '+tag+'_exp_service\nadd_political_power = -20'),
             ('Use the reserve for immediate recovery.','add_stability = 0.03\nif = { limit = { ac_ucw_active = yes } add_to_variable = { ac_ucw_recovery = 6 } ac_ucw_bound = yes }\nelse_if = { limit = { ac_pwi_active = yes } add_to_variable = { ac_pwi_recovery = 4 } ac_pwi_bound_pressures = yes }')])
        ready={1:'opening_ready',2:'choice_2_ready',3:'choice_3_ready',4:'assessment_ready'}
        for i,suffix in ready.items():
            flag=tag+'_exp_event_'+str(i)
            condition='original_tag = '+tag+' has_country_flag = '+tag+'_exp_'+suffix+event_deadline(i)
            if i==1:condition+=' date < '+('2000.1.1' if tag=='REC' else '1999.12.1')
            dispatch.append(once(flag+'_sent','country_event = { id = ac_expansion.'+str(TAGS.index(tag)*10+i)+' days = 1 }',condition+' ac_exp_eligible = yes'))
    EFFECTS.append(block('ac_exp_weekly','\n'.join(dispatch)))
    put('events/ac_expansion.txt','\n'.join(EVENTS))
    put('common/scripted_effects/ac_expansion.txt','\n'.join(EFFECTS))
    put('common/scripted_triggers/ac_expansion.txt',block('ac_exp_eligible','has_capitulated = no'))
    weekly='\n'.join(block('on_weekly_'+tag,block('effect','ac_exp_weekly = yes')) for tag in TAGS)
    put('common/on_actions/ac_expansion.txt',block('on_actions',weekly))

def build_policies():
    categories=[];decisions=[]
    for tag,(name,*_) in COUNTRY_TEXT.items():
        policies=[
            ('civil','Public Administrative Review','Published allocations and appeals improve public confidence. Maintaining the review process consumes political attention.','stability_factor = 0.03\npolitical_power_gain = -0.05'),
            ('directive','Directive Administration','A concentrated administrative chain supports military readiness while weakening confidence in civilian oversight.','army_org_factor = 0.03\nstability_factor = -0.02'),
            ('service','Standing Recovery Service','Experienced repair and relief staff reduce disruption. Maintaining the permanent service ties up civilian resources.','supply_consumption_factor = -0.03\nconsumer_goods_factor = 0.01')]
        if tag=='FCU':policies=[(key,*value[:3]) for key,value in FCU_POLICIES.items()]
        for suffix,title,description,modifier in policies:
            ident=tag+'_exp_'+suffix;loc(ident,name+': '+title);loc(ident+'_desc',description)
            IDEAS.append(block(ident,'picture = ac_exp_'+tag.lower()+'_'+suffix+'\nallowed = { always = no }\nallowed_civil_war = { always = no }\nremoval_cost = -1\n'+block('modifier',modifier)))
        category=tag+'_exp_programmes';ident=tag+'_exp_maintain_services'
        loc(category,name+': Public Programmes');loc(category+'_desc','Review the continuing cost of the completed national programmes.')
        loc(ident,'Rehearse the Recovery Services');loc(ident+'_desc','Spend political authority on a recurring exercise of repair and relief procedures. The exercise improves the current recovery effort, but can only be repeated after six months. It requires a completed programme and an active recovery system.')
        categories.append(block(category,'icon = ac_exp_'+tag.lower()+'_programmes\nallowed = { original_tag = '+tag+' }\nvisible = { has_country_flag = '+tag+'_exp_event_4_answered }'))
        guard='ac_exp_eligible = yes has_country_flag = '+tag+'_exp_event_4_answered OR = { ac_ucw_active = yes ac_pwi_active = yes }'
        reward='if = { limit = { ac_ucw_active = yes } add_to_variable = { ac_ucw_recovery = 2 } ac_ucw_bound = yes }\nelse_if = { limit = { ac_pwi_active = yes } add_to_variable = { ac_pwi_recovery = 2 } ac_pwi_bound_pressures = yes }'
        decisions.append(block(category,block(ident,'icon = '+ident+'\nallowed = { original_tag = '+tag+' }\navailable = { '+guard+' }\ncost = 45\nfire_only_once = no\ndays_re_enable = 180\nai_will_do = { base = 1 }\n'+block('complete_effect',block('if','limit = { '+guard+' }\n'+reward)))))
    put('common/ideas/ac_expansion.txt',block('ideas',block('country','\n'.join(IDEAS))))
    put('common/decisions/categories/ac_expansion.txt','\n'.join(categories))
    put('common/decisions/ac_expansion.txt','\n'.join(decisions))
    put('common/opinion_modifiers/ac_expansion.txt',block('opinion_modifiers',block('ac_exp_scientific_exchange','value = 10\nyears = 3')))
    loc('ac_exp_scientific_exchange','Civilian Scientific Exchange')

def main():
    p=argparse.ArgumentParser();p.add_argument('--check',action='store_true');a=p.parse_args()
    build_trees();build_narrative();build_policies()
    loc('ac_exp_opening_brief_tt','A cabinet brief will present a choice about public accounts and coordinating staff at the next weekly review.')
    existing=set()
    for path in (MOD/'localisation/english').glob('*.yml'):
        if path.name!='ac_expansion_l_english.yml':existing.update(re.findall(r'^\s*([\w.]+):\d*\s+"',path.read_text(encoding='utf-8-sig'),re.M))
    for key in sorted(set(re.findall(r'has_(?:country|global)_flag\s*=\s*(\w+)', '\n'.join(OUT.values())))):
        if key not in existing and key not in LOC:
            title=('Completed: '+LOC[key[:-5]]) if key.endswith('_done') and key[:-5] in LOC else key.replace('_exp_',' — ').replace('_',' ').capitalize()
            loc(key,title)
    put('localisation/english/ac_expansion_l_english.yml','l_english:\n'+'\n'.join(' '+k+':0 "'+v.replace('"','\\"').replace('\n','\\n')+'"' for k,v in LOC.items())+'\n')
    failures=[]
    for path,text in OUT.items():
        encoding='utf-8-sig' if path.endswith('.yml') else 'utf-8';data=text.encode(encoding);target=MOD/path
        if a.check:
            if not target.exists() or target.read_bytes().replace(b'\r\n',b'\n')!=data:failures.append(path)
        else:target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes(data)
    if failures:raise SystemExit('Generated expansion content differs: '+', '.join(failures))
    print('Expansion:',len(FOCUSES),'new focuses, 20 narrative events,',len(IDEAS),'policies, 5 continuing decisions;',len(OUT),'files'+(' checked.' if a.check else ' generated.'))

if __name__=='__main__':main()
